dict(id='9.1',sub='Ethics',nb=['ca'],ch=[],tag='M',t='Ethics of slowing down AI',
 ctx='Anthropic\'s CEO called for AI firms to "pace the frontier" until safety checks catch up.',
 pts=['Stakeholder dilemmas: companies (competition vs responsibility), governments (innovation vs public safety), citizens (benefits vs involuntary risks), developing countries (safety vs equal opportunity), future generations.',
 'Ethical concerns: precaution vs innovation (precautionary principle, non-maleficence; Asilomar 1975 after the 1974 pause); duty to benefit (beneficence; AlphaFold, 2024 Chemistry Nobel); collective action dilemma (FLI 2023 six-month pause letter); self-regulation vs public accountability (independent evaluators with access); distributive and intergenerational justice (India\'s AI Governance Guidelines 2025 "Innovation over Restraint"; New Delhi Declaration on AI Impact 2026).',
 'Way forward: risk-based safeguards, purposeful pauses, independent scrutiny, coordinated governance, inclusive decisions.'],
 pro=[],mains=['Thinkers: Hans Jonas (ethics of responsibility); Collingridge dilemma; utilitarianism and duty ethics.','Keywords: precautionary principle, non-maleficence, beneficence, collective action problem, probity, responsible innovation.'],kw='Precautionary principle',pyq=''),
dict(id='9.2',sub='Ethics',nb=['ca'],ch=[],tag='M',t='Ethics of AI in health research',
 ctx='September 2026 WHO report urged stronger ethical oversight; it cites ICMR Ethical Guidelines for AI in Biomedical Research and Healthcare (2023).',
 pts=['Dilemmas: informed consent vs secondary data use (Royal Free-DeepMind 1.6 million records, 2015); accuracy vs fairness (US algorithm using past spending underestimated Black patients\' needs); beneficence vs non-maleficence (sepsis tool missed about two-thirds of cases, 2021 study); problem of many hands; health data colonialism and ethics dumping (Kenyan labellers paid under $2/hour, 2023).',
 'Way forward: meaningful consent, bias and safety audits, skilled ethics committees, clear accountability, fair benefit-sharing.'],
 pro=[],mains=['Kant (ends, not means); Rawls (benefits to least advantaged); Belmont Report 1979 (respect for persons, beneficence, justice); Gandhi\'s "Science without humanity". Case: Havasupai tribe (US, 2010).'],kw='Informed consent; Ethics dumping',pyq=''),
dict(id='9.3',sub='Ethics',nb=['ca'],ch=[],tag='M',t='Dark patterns and ethics of consumer choice',
 ctx='CCPA imposed Rs 10 lakh penalty on Rapido (September 2026) over misleading payment prompts. ASCI-Parallel study 2024 found dark patterns in 52 of 53 popular apps. CCPA Guidelines 2023 specify 13 types.',
 pts=['Persuasion vs manipulation (false urgency timers, confirm shaming); formal consent vs meaningful choice (subscription trap); transparency vs asymmetry (drip pricing); profit vs vulnerability (health-tech apps averaged 8.8 instances); commercial targets vs professional integrity (basket sneaking).',
 'Way forward: transparent offers, equal ease of choice, ethics by design, internal accountability, effective enforcement.'],
 pro=[],mains=['Kant; Gandhi\'s "Commerce without morality"; Thaler and Sunstein, Nudge. Cases: Amazon Prime FTC $2.5 billion (2025); Google and Facebook France cookie fines (2022); Zepto Rs 7 lakh CCPA penalty (2025).'],kw='Choice architecture',pyq=''),
